function Dashboard() {
  const [tableData, setTableData] = useState([]);
  const [chartData, setChartData] = useState({ labels: [], series: [] });
  const [selectedStation, setSelectedStation] = useState(0);
  const [stats, setStats] = useState({ busStops: 0 });

  const stationNames = ["วิศวะ", "วิทยาศาสตร์", "ศิลปศาสตร์", "PKY"];

  const fetchData = async () => {
    try {
      const statsRes = await fetch("http://localhost:3000/api/dashboard-stats");
      const statsJson = await statsRes.json();
      setStats({ busStops: statsJson.capacity || 0 });

      const tableRes = await fetch("http://localhost:3000/api/table-data");
      const tableJson = await tableRes.json();
      setTableData(Array.isArray(tableJson) ? tableJson : tableJson.data || []);

      const chartRes = await fetch("http://localhost:3000/api/chart-data");
      const chartJson = await chartRes.json();
      setChartData({ labels: chartJson.labels || [], series: chartJson.series || [] });
    } catch (err) {
      console.error("ดึงข้อมูลผิดพลาด:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 10000);
    return () => clearInterval(interval);
  }, []);

  const barChartData = {
    labels: chartData.labels,
    series: [chartData.series[selectedStation] || []],
  };

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      const color = data.value.y > 20 ? "#dc3545" : "#198754";
      data.element.attr({ style: `stroke: ${color}; stroke-width: 30px;` });
      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 15,
        style: "font-size:14px;fill:#000;font-weight:bold;text-anchor:middle",
      }).text(data.value.y);
    }
  };

  return (
    <div style={{ minHeight: "100vh" }}>
      <style>{themeStyle}</style>

      <div className="header-blue-bg">
        <Container fluid className="px-4">
          <h2 className="text-white fw-bold">DASHBOARD</h2>
        </Container>
      </div>

      <Container fluid className="px-4">
        {/* ส่วนแสดงจำนวนจุดจอดทั้งหมด */}
        <Row className="g-3">
          <Col lg="3" md="6" xs="12">
            <Card>
              <Card.Body className="d-flex justify-content-between align-items-center">
                <div>
                  <p className="text-uppercase text-muted small fw-bold mb-1">จุดจอดรถเมล์</p>
                  <h4 className="fw-bold mb-0">{stats.busStops} Stops จุด</h4>
                </div>
                <div className="bg-danger text-white rounded-circle p-2 d-flex align-items-center justify-content-center" style={{width:'45px', height:'45px'}}>
                  🚌
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>

        {/* ตารางแสดงสถานะ: สถานีไหน มีคนเท่าไหร่ */}
        <Row className="mt-2">
          <Col xs="12">
            <Card>
              <Card.Header className="bg-white border-0 pt-4">
                <Card.Title as="h5" className="fw-bold">สถานะจุดจอดรถ</Card.Title>
              </Card.Header>
              <Card.Body className="p-0">
                {/* แสดงผลบน Desktop */}
                <div className="desktop-table">
                  <Table className="table-clean mb-0">
                    <thead>
                      <tr>
                        <th>สถานี</th>
                        <th>ผู้โดยสาร</th>
                        <th>สถานะ</th>
                        <th>อัปเดต</th>
                      </tr>
                    </thead>
                    <tbody>
                      {tableData.map((item, index) => (
                        <tr key={index}>
                          <td className="fw-normal">{item.stationName}</td>
                          <td>{item.passengerCount} คน</td>
                          <td>
                            <Badge bg={item.passengerCount > 20 ? "danger" : "success"} className="px-2 py-1">
                              {item.passengerCount > 20 ? "หนาแน่น" : "ปกติ"}
                            </Badge>
                          </td>
                          <td className="text-muted small">
                            {item.timestamp ? new Date(item.timestamp).toLocaleTimeString("th-TH") : "-"}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </Table>
                </div>

                {/* แสดงผลบน Mobile */}
                <div className="mobile-only">
                  {tableData.map((item, index) => (
                    <div className="mobile-status-card" key={index}>
                      <div className="d-flex justify-content-between align-items-center mb-1">
                        <span className="fw-bold">{item.stationName}</span>
                        <Badge bg={item.passengerCount > 20 ? "danger" : "success"}>
                          {item.passengerCount > 20 ? "หนาแน่น" : "ปกติ"}
                        </Badge>
                      </div>
                      <div className="small text-muted">ผู้โดยสาร: {item.passengerCount} คน</div>
                    </div>
                  ))}
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>

        {/* ส่วนเลือกสถานีเพื่อดูสถิติ */}
        <Row className="mt-3">
          <Col xs="12">
            <Card>
              <Card.Header className="bg-white border-0 pt-3">
                <Card.Title as="h5">เลือกสถานี</Card.Title>
              </Card.Header>
              <Card.Body>
                <div className="station-scroll-container">
                  {stationNames.map((name, index) => (
                    <Button
                      key={index}
                      variant={selectedStation === index ? "outline-primary" : "outline-secondary"}
                      onClick={() => setSelectedStation(index)}
                      className="btn-station"
                      style={selectedStation === index ? {borderWidth: '2px'} : {color: '#94a3b8'}}
                    >
                      {selectedStation === index && <span>📍</span>}
                      {name}
                    </Button>
                  ))}
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>

        {/* กราฟสถิติรายชั่วโมงของสถานีที่เลือก */}
        <Row className="mt-3 pb-5">
          <Col xs="12">
            <Card>
              <Card.Header className="bg-white border-0 pt-4">
                <Card.Title as="h6" className="fw-bold">
                  สถิติ: {stationNames[selectedStation]} 📍
                </Card.Title>
              </Card.Header>
              <Card.Body>
                <div className="chart-scroll">
                  <div style={{ width: Math.max(chartData.labels.length * 70, 600), height: "400px" }}>
                    <ChartistGraph
                      data={barChartData}
                      type="Bar"
                      options={{
                        height: "400px",
                        axisX: { showGrid: false, offset: 60 },
                        axisY: { onlyInteger: true, low: 0, high: Math.max(...(chartData.series[selectedStation] || [0])) + 5 },
                        chartPadding: { left: 20, right: 20, top: 40, bottom: 40 },
                        fullWidth: true,
                      }}
                      listener={{ draw: drawBarLabels }}
                    />
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </div>
  );
}

export default Dashboard;
